// If running in "Run Once for All Items", n8n provides `items` array
const processedItems = items.map(item => {
  const inputJson = item.json || {};
  const inputBinary = item.binary || {};

  // Check that a binary file exists
  if (Object.keys(inputBinary).length === 0) {
    throw new Error("No file uploaded in this item");
  }

  // Get the binary key dynamically (image, file, etc.)
  const binaryKey = Object.keys(inputBinary)[0];
  const binaryData = inputBinary[binaryKey];

  // Create filename safely
  const topic = inputJson.body?.topic || "image";
  const newFileName = topic.replace(/ /g, "_") + "_" + Date.now() + ".jpg";

  return {
    json: {
      ...inputJson,      // keep original JSON
      fileName: newFileName // add new filename
    },
    binary: {
      [binaryKey]: binaryData // preserve original binary
    }
  };
});

return processedItems;
